+        for (Vector3i blockPos : boxTraverseBlocks(start, end, boundingBox)) {
+            WrappedBlockState blockState = player.compensatedWorld.getBlock(blockPos);
+            StateType blockType = blockState.getType();
+
+            if (blockType.isAir()) {
